home=function(){return `<div class="store-home"><section class="campaign"><img class="campaign-image" src="assets/campaign.webp" alt="Original Suits.me campaign: forest green tailoring in a sunlit courtyard" fetchpriority="high"><div class="campaign-shade"></div><div class="campaign-copy"><span class="eyebrow">THE NEW SEASON, TAILORED TO YOU</span><h1>Distinct by design.<br>Yours by measure.</h1><p>Considered fabrics. Personal details.<br>A fit that could only be yours.</p><div class="campaign-actions"><a class="btn orange" href="/collections/suits">Shop suits <span>↗</span></a><a class="btn ghost" href="/measure">Find your fit <span>→</span></a></div></div><div class="campaign-bottom"><span>THE FOREST EDIT &nbsp; / &nbsp; AUTUMN 2026</span><a href="/product/5">Explore this look ↗</a></div></section><div class="service-band"><span>✧ &nbsp; MADE TO YOUR MEASUREMENTS</span><span>✧ &nbsp; YOUR FABRIC. YOUR FINISH.</span><span>✧ &nbsp; PERSONAL TAILORING, SIMPLIFIED</span></div><section class="shop-section"><div class="shop-section-head"><div><div class="eyebrow">YOUR STYLE STARTS HERE</div><h2>The considered collection.</h2></div><a class="textlink" href="/collections/suits">Shop all suits ↗</a></div><div class="products">${homeProducts()}</div><p class="ai-note">Original AI-generated style imagery · Illustrative collection and pricing</p></section><section class="fabric-edit"><div class="fabric-intro"><span class="eyebrow">FIND YOUR FABRIC</span><h2>It begins<br>with the cloth.</h2><p>From soft wool to expressive tweed, discover a texture that feels like you.</p><a class="textlink" href="/collections/fabrics">Explore fabric samples ↗</a></div><a class="fabric-tile" href="/collections/suits/wool-suits"><img src="assets/model-navy.webp" alt="Navy wool tailoring" loading="lazy"><div><span>THE EVERYDAY ORIGINAL</span><h3>Wool</h3><span class="tile-link">Explore wool suits ↗</span></div></a><a class="fabric-tile" href="/collections/suits/tweed-suits"><img src="assets/model-tweed.webp" alt="Brown herringbone tweed tailoring" loading="lazy"><div><span>CHARACTER IN EVERY THREAD</span><h3>Tweed</h3><span class="tile-link">Explore tweed suits ↗</span></div></a><a class="fabric-tile" href="/collections/suits/linen-suits"><img src="assets/model-sand.webp" alt="Light sand linen tailoring" loading="lazy"><div><span>A LIGHTER WAY TO DRESS</span><h3>Linen</h3><span class="tile-link">Explore linen suits ↗</span></div></a></section><section class="occasion-section"><div class="shop-section-head"><div><span class="eyebrow">DRESS FOR YOUR MOMENT</span><h2>Every day. The big day.</h2></div></div><div class="occasion-grid"><a class="occasion-card" href="/collections/weddings"><img src="assets/model-sand.webp" alt="Sand linen wedding suit" loading="lazy"><div><span class="eyebrow">FOR THE DAYS YOU REMEMBER</span><h3>The wedding edit.</h3><span class="tile-link">Find your wedding suit ↗</span></div></a><a class="occasion-card" href="/collections/jackets"><img src="assets/model-jacket.webp" alt="Taupe sport coat styled casually" loading="lazy"><div><span class="eyebrow">A DIFFERENT KIND OF EVERYDAY</span><h3>Off-duty, well dressed.</h3><span class="tile-link">Explore jackets ↗</span></div></a></div></section><section class="fit-story"><div class="fit-photo"><img src="assets/model-fabrics.webp" alt="Tailoring fabric textures and tools" loading="lazy"></div><div class="fit-copy"><span class="eyebrow">THE MEASUREMENT STUDIO</span><h2>Great style starts<br>with your proportions.</h2><p>A tape measure. A little guidance. A profile that’s yours to keep. Our step-by-step studio takes you from first measurement to final review.</p><div class="fit-points"><span><b>01</b> Choose your starting point</span><span><b>02</b> Follow the illustrated guide</span><span><b>03</b> Save your personal fit</span></div><a class="btn orange" href="/measure">Create my fit profile →</a></div></section><section class="shop-section"><div class="shop-section-head"><div><span class="eyebrow">THE WARDROBE, RECONSIDERED</span><h2>Beyond the two-piece.</h2></div><a class="textlink" href="/collections/women">Explore women’s tailoring ↗</a></div><div class="products">${productGrid([6,12,13,16])}</div></section><section class="craft-story" id="craft"><img src="assets/craftsmanship-BxSjRaOO.jpg" alt="The craft of personal tailoring" loading="lazy"><div><span class="eyebrow">THE HUMAN TOUCH</span><h2>Made with purpose.<br>Worn with confidence.</h2><p>It’s the small decisions that make something personal. The way a lapel sits. The fabric you reach for. The proportions that feel right.</p><a class="btn light" href="/locations">Meet us in a showroom ↗</a></div></section><section class="journey-section"><span class="eyebrow">FROM THE FIRST CHOICE TO THE FINAL DETAIL</span><h2>Your suit. Your way.</h2><div class="journey-grid"><a href="/collections/suits"><b>01</b><h3>Choose your cloth.</h3><p>Find the texture, color, and garment for your wardrobe.</p><span>Explore the collection →</span></a><a href="/customize"><b>02</b><h3>Make it personal.</h3><p>Refine the lapel, lining, silhouette, and finishing touches.</p><span>Design your suit →</span></a><a href="/measure"><b>03</b><h3>Find your fit.</h3><p>Build and save a measurement profile, one step at a time.</p><span>Open the measurement studio →</span></a></div></section></div>`};
function catalogItems(cat,topic){let list=products.map((p,i)=>({...p,index:i}));if(cat==='Weddings')list=list.filter(p=>p.category==='Suits'&&[0,3,4,5].includes(p.index));else if(cat==='Fabrics')list=list.filter(p=>p.kind==='swatch');else if(cat==='Accessories')list=list.filter(p=>p.kind==='accessory');else list=list.filter(p=>p.category===cat);let fabric=topic?.match(/wool|linen|tweed|cotton/i)?.[0];if(fabric){let m=list.filter(p=>p.fabric.toLowerCase().includes(fabric.toLowerCase()));if(m.length)list=m}if(/waistcoat/i.test(topic))list=list.filter(p=>p.kind==='waistcoat');if(/two piece/i.test(topic))list=list.filter(p=>p.index!==4&&p.index!==5);if(/three piece/i.test(topic))list=list.filter(p=>p.index===4);if(/double breasted/i.test(topic))list=list.filter(p=>p.index===5);if(cat==='Women'&&topic&&/^(Jackets|Trousers|Suits)$/.test(topic)){const kind={Jackets:'jacket',Trousers:'pants',Suits:'suit'}[topic];list=list.filter(p=>p.kind===kind)}return list}
categoryCollection=function(hash){let bits=hash.split('/').map(decodeURIComponent),cat=bits[1]||'Suits',topic=bits[2]||'';if(catalogRoute!==hash){catalogRoute=hash;selectedCatalog=cat;currentTopic=topic;searchText='';catalogFabric='All fabrics';catalogSort='featured'}let list=catalogItems(cat,topic);const count=list.length;list=list.filter(p=>(catalogFabric==='All fabrics'||p.fabric===catalogFabric)&&(!searchText||(p.name+' '+p.fabric+' '+p.color).toLowerCase().includes(searchText.toLowerCase())));if(catalogSort==='low')list.sort((a,b)=>a.price-b.price);if(catalogSort==='high')list.sort((a,b)=>b.price-a.price);const title=topic&&!/^Shop all|Popular|New arrivals/i.test(topic)?topic:cat==='Weddings'?'The wedding edit':cat==='Women'?'Women’s tailoring':cat==='Fabrics'?'The fabric studio':cat==='Accessories'?'The finishing touches':cat;const intro={Suits:'From your everyday signature to something a little unexpected. Find your cloth, then make it your own.',Jackets:'The layer that brings it all together. Personal tailoring for workdays, weekends, and everything between.',Trousers:'Considered proportions. Comfortable movement. The foundation of a well-dressed wardrobe.',Shirts:'A crisp starting point for every outfit. A clean silhouette, made around you.',Women:'Refined silhouettes, thoughtfully proportioned. Discover tailoring with a personal point of view.',Weddings:'For the photographs, the first dance, and everything you’ll remember.',Accessories:'The small details that make the whole look feel personal.',Fabrics:'Get closer to the cloth. Explore the textures behind your next custom garment.'};return `<section class="catalog-heading"><div class="breadcrumb"><a href="/">Home</a> / ${esc(cat)}${topic?' / '+esc(topic):''}</div><span class="eyebrow">THE SUITS.ME COLLECTION</span><h1>${esc(title)}.</h1><p>${intro[cat]||intro.Suits}</p></section><section class="catalog-body"><div class="catalog-toolbar"><div class="filter-chips">${['Suits','Jackets','Trousers','Shirts','Women','Accessories','Fabrics'].map(c=>`<a class="chip ${c===cat?'active':''}" href="${realUrl('#collection/'+c)}">${c}</a>`).join('')}</div><span class="subtle">${count} ${count===1?'style':'styles'}</span></div><div class="catalog-controls"><input type="search" aria-label="Search this collection" placeholder="Search by style, fabric or color" value="${esc(searchText)}" onchange="searchText=this.value;render(false)"><select aria-label="Filter by fabric" onchange="catalogFabric=this.value;render(false)">${['All fabrics',...new Set(catalogItems(cat,topic).map(p=>p.fabric))].map(f=>`<option ${f===catalogFabric?'selected':''}>${f}</option>`).join('')}</select><select aria-label="Sort products" onchange="catalogSort=this.value;render(false)"><option value="featured">Featured</option><option value="low" ${catalogSort==='low'?'selected':''}>Price: low to high</option><option value="high" ${catalogSort==='high'?'selected':''}>Price: high to low</option></select></div>${list.length?`<div class="products">${list.map(p=>productCard(p,p.index)).join('')}</div>`:`<div class="empty-search"><h2>Let’s try another combination.</h2><p>No styles match those filters.</p><button class="btn light" onclick="searchText='';catalogFabric='All fabrics';render(false)">Clear filters →</button></div>`}<p class="ai-note">Original AI-generated styling references. Product specifications and prices are illustrative in this design preview.</p></section>`};
chooseProduct=function(i){editingBagId=null;pendingOrderAttach=null;config={product:i,fabric:products[i].color,lapel:'Notch',closure:'Two button',fit:'Tailored',lining:'Tonal',monogram:'',profileId:config.profileId};saveConfig();stage=0;location.hash='#product/'+i;render()};
function productPage(i){const p=products[i];if(!p)return categoryCollection('#collection');if(p.kind==='gift')return giftPage();const direct=['accessory','swatch'].includes(p.kind);return `<section class="product-page"><div class="breadcrumb"><a href="${realUrl('#collection/'+p.category)}">${p.category}</a> / ${p.name}</div><div class="product-detail"><div class="detail-photo ${p.kind==='pants'?'pants-photo':''}"><img src="assets/${p.img}" alt="${p.name}" style="object-position:${p.pos||'center'}"><span>ORIGINAL AI-GENERATED STYLE IMAGE</span></div><div class="detail-copy"><span class="eyebrow">${p.tag}</span><h1>${p.name}</h1><div class="detail-price">${money(p.price)} <span>USD</span></div><p>${p.description}</p><div class="detail-facts"><div><span>Fabric</span><strong>${p.fabric}</strong></div><div><span>Color</span><strong>${p.color}</strong></div><div><span>Includes</span><strong>${{suit:'Jacket & trousers'+(i===4?' & waistcoat':''),jacket:'Jacket only',waistcoat:'Waistcoat only',pants:'Trousers only',shirt:'Shirt only',accessory:'Tie, pocket square & cufflinks',swatch:'Three fabric samples'}[p.kind]}</strong></div></div><button class="btn orange" onclick="${direct?'addDirect('+i+')':'beginDesign('+i+')'}">${direct?'Add to bag':'Customize & find my fit'} →</button><p class="subtle">${direct?'':'Made to order. '}${deliveryEstimateText()}</p><p class="subtle">${direct?'A finishing touch to your personal wardrobe.':'Personal details · Guided measurements · Saved fit profiles'}</p><details open class="product-accordion"><summary>The details</summary><p>${p.description} Photography shows one styling combination. Selected options are recorded in your configuration.</p></details><details class="product-accordion"><summary>Fit & measurements</summary><p>${direct?'No measurement profile is needed for this item.':'Choose a saved profile or follow our illustrated measurement guide. Use body measurements without adding extra ease. Your fit preference is recorded separately.'}</p><a class="textlink" href="/measure">Visit the measurement studio →</a></details><details class="product-accordion"><summary>Care & delivery</summary><p>For tailored garments, professional garment care is recommended. Confirm the care label and delivery estimate with your stylist before placing a production order.</p><a class="textlink" href="/help">Customer care →</a></details></div></div><div class="shop-section-head" style="margin-top:65px"><h2>Consider these, too.</h2></div><div class="products">${productGrid(products.map((p,n)=>n).filter(n=>n!==i&&products[n].category===p.category).length?products.map((p,n)=>n).filter(n=>n!==i&&products[n].category===p.category).slice(0,4):[0,6,12,16].filter(n=>n!==i))}</div></section>`}
function beginDesign(i){editingBagId=null;pendingOrderAttach=null;if(config.product!==i){config.lapel='Notch';config.closure='Two button';config.fit='Tailored';config.lining='Tonal';config.monogram='';delete config.vents;delete config.cuffButtons;delete config.pocketAccent;delete config.liningType;delete config.buttons;delete config.elbowPatches;delete config.pantsLining;delete config.pocketStyle;delete config.pleats;delete config.backPockets;delete config.beltLoops;delete config.tier;delete config.vest;delete config.vestFabricBack;delete config.additionalPants;delete config.squareAndTie;delete config.monogram2;delete config.collarMonogram;delete config.workingCuffButtons;delete config.pickStitch;delete config.gauntletCuff;delete config.naturalShoulders;delete config.boatPocket;delete config.milaneseButtonhole;delete config.pantsCuff;delete config.suspenderButtons;delete config.coinPocket;delete config.wideWaistband;delete config.sideTabs;delete config.tailorChanges;delete config.comments}config.product=i;config.fabric=products[i].color;saveConfig();if(['pants','shirt','waistcoat'].includes(products[i].kind)){config.lapel='';config.closure=products[i].kind==='pants'?'Flat front':products[i].kind==='shirt'?'Spread collar':'Five button';saveConfig()}if(products[i].kind==='suit'&&products[i].category==='Women')config.trouserFront='Flat front';else delete config.trouserFront;if(!['suit','jacket'].includes(products[i].kind)){delete config.vents;delete config.cuffButtons;delete config.pocketAccent;delete config.liningType;delete config.buttons;delete config.elbowPatches;delete config.tier;delete config.squareAndTie;delete config.monogram2;delete config.collarMonogram;delete config.workingCuffButtons;delete config.pickStitch;delete config.gauntletCuff;delete config.naturalShoulders;delete config.boatPocket;delete config.milaneseButtonhole}if(products[i].kind!=='suit'){delete config.pleats;delete config.vest;delete config.vestFabricBack;delete config.additionalPants;delete config.tailorChanges}if(!['suit','pants'].includes(products[i].kind)){delete config.pantsLining;delete config.pocketStyle;delete config.backPockets;delete config.beltLoops;delete config.pantsCuff;delete config.suspenderButtons;delete config.coinPocket;delete config.wideWaistband;delete config.sideTabs}if(!['suit','jacket','pants'].includes(products[i].kind))delete config.comments;saveConfig();stage=0;location.hash='#customize';render()}
const baseMeasure=measure,baseStartMeasurements=startMeasurements;
startMeasurements=function(){draft.wearer=products[config.product]?.silhouette==='Boys two-piece'?'Boys':products[config.product]?.category==='Women'?'Women':'Men';noteGarmentContext(products[config.product]?.kind);saveDraft();baseStartMeasurements()};
measure=function(){if(garmentMode())return baseMeasure();if(['Women','Boys'].includes(draft.wearer))draft.method='body';let html=baseMeasure();if(['Women','Boys'].includes(draft.wearer)){html=html.replace(/<button class="method [^"]*" onclick="setMethod\('ready'\)">[\s\S]*?<\/button>/,'').replace('Choose the starting point that works for you.','Follow our illustrated body-measurement guide for your tailored fit.').replace(/>Chest</g,'>Bust / chest<').replace('Wrap the tape around the fullest part of your chest, under your arms. Keep it level across your back. Stand naturally and do not inflate your chest.','Wrap the tape around the fullest part of your bust, keeping it level across your back. Stand naturally and do not pull the tape tight.');}if(draft.wearer==='Boys')html=html.replace('Follow our illustrated body-measurement guide for your tailored fit.','An adult helper should take and check these measurements. Confirm the child’s fit with your stylist before production.').replace('Bust / chest','Chest').replace('Wrap the tape around the fullest part of your bust, keeping it level across your back. Stand naturally and do not pull the tape tight.','An adult helper should measure around the fullest part of the chest, keeping the tape level and comfortably close.');return html};
const originalCustomize=customize;
