function checkoutPage(){if(!bag.length)return `<section class="center-page"><span class="eyebrow">YOUR PERSONAL SELECTION</span><h1>Let’s find your first piece.</h1><p>Your bag is empty. Explore the collection to start your order.</p><a class="btn orange" href="/collections/suits">Shop the collection →</a></section>`;const quoteKey=JSON.stringify({bag,checkout}),shownQuote=paymentConfig.ready&&paymentConfig.mode==='live'&&checkoutQuote&&checkoutQuote.key===quoteKey&&!checkoutQuote.failed?checkoutQuote:null;if(paymentConfig.ready&&paymentConfig.mode==='live'&&checkoutStage===1)fetchCheckoutQuote();return `<section class="checkout-page"><div class="breadcrumb"><a href="/">Home</a> / Checkout</div><span class="eyebrow">YOUR PERSONAL TAILORING JOURNEY</span><h1>The final details.</h1><div class="checkout-grid"><div><div class="checkout-steps"><span class="${checkoutStage===0?'active':''}">01 Contact & delivery</span><span class="${checkoutStage===1?'active':''}">02 Review & payment</span></div>${accountStrip()}${checkoutStage===0?`<form id="checkoutForm" onsubmit="event.preventDefault();saveCheckoutForm(this)"><h2>Where should it go?</h2><p>Enter your details, then review your design and fit.</p><label class="field">Email<input name="email" type="email" required maxlength="150" value="${esc(checkout.email)}" autocomplete="email"></label><div class="input-grid">${[['firstName','First name','given-name'],['lastName','Last name','family-name']].map(([k,l,a])=>`<label class="field">${l}<input name="${k}" required maxlength="60" autocomplete="${a}" value="${esc(checkout[k])}"></label>`).join('')}</div><label class="field">Street address<input name="address" required maxlength="150" autocomplete="street-address" value="${esc(checkout.address)}"></label><div class="input-grid"><label class="field">City<input name="city" required maxlength="80" autocomplete="address-level2" value="${esc(checkout.city)}"></label><label class="field">State<input name="state" required minlength="2" maxlength="2" autocomplete="address-level1" value="${esc(checkout.state)}"></label><label class="field">ZIP code<input name="zip" required pattern="[0-9]{5}(-[0-9]{4})?" inputmode="numeric" autocomplete="postal-code" value="${esc(checkout.zip)}"></label><label class="field">Country<select name="country"><option value="US">United States</option></select></label></div><p class="subtle">Design preview: use sample details to test the checkout.</p><button class="btn orange" type="submit">Review my order →</button></form>`:`<h2>Everything, just as you chose.</h2><div class="delivery-summary"><strong>${esc(checkout.firstName)} ${esc(checkout.lastName)}</strong><p>${esc(checkout.address)}<br>${esc(checkout.city)}, ${esc(checkout.state)} ${esc(checkout.zip)}<br>${esc(checkout.email)}</p><button class="help" onclick="checkoutStage=0;render(false)">Edit delivery details</button></div><div class="payment-choice"><span class="payment-mark">Authorize.Net</span><h3>${paymentConfig.ready?'Secure hosted payment':'Try the complete checkout'}</h3><p>${paymentConfig.ready?'Continue to the secure Authorize.Net payment form. Your card details are entered directly with the payment provider.':'This demonstration records a sample order without requesting card details or charging you.'}</p></div>${bag.some(x=>x.profile?.method==='deferred')?'<div class="note">Measurements to follow: at least one item in this order has no measurements yet. You can add them from your order page after checkout. We cannot start making those garments until the measurements arrive.</div>':''}<label class="check-line"><input id="orderConsent" type="checkbox">I’ve reviewed the items, customization, and measurement profiles in this order.</label><div id="checkoutError" class="error" role="alert"></div><button class="btn orange" id="placeOrder" onclick="submitCheckout()">${paymentConfig.ready?'Continue to Authorize.Net':'Place demo order'} →</button><p class="subtle" style="margin-top:15px">${paymentConfig.ready?'Secure checkout powered by Authorize.Net.':'Demo order · No payment · No production submission'}</p>`}</div><aside class="order-summary"><h2>Your selection.</h2>${bag.map(x=>lineHtml(x,false)).join('')}<div class="summary-row"><span>Subtotal</span><strong>${money(subtotal())}</strong></div><div class="summary-row"><span>Delivery</span><span>${shownQuote?money(shownQuote.shippingCents/100):paymentConfig.ready?(paymentConfig.mode==='sandbox'?'Not charged in sandbox':'Calculated by merchant settings'):'Included in demo'}</span></div><div class="summary-row"><span>Tax</span><span>${shownQuote?money(shownQuote.taxCents/100):paymentConfig.ready?(paymentConfig.mode==='sandbox'?'Not charged in sandbox':'Calculated before payment'):'Not charged in demo'}</span></div><div class="total"><span>${shownQuote?'Total':paymentConfig.ready?(paymentConfig.mode==='sandbox'?'Total':'Merchandise total'):'Demo total'}</span><strong>${money(shownQuote?shownQuote.totalCents/100:subtotal())}</strong></div><p class="subtle" style="margin-top:12px">${deliveryEstimateText()}</p><details class="product-accordion"><summary>Review measurement profiles</summary>${bag.map(x=>`<div class="mini-profile"><strong>${esc(x.profile?.name||'No profile required')}</strong>${profileSummary(x)?`<p>${esc(profileSummary(x))}</p>`:''}</div>`).join('')}</details></aside></div></section>`}
function saveCheckoutForm(form){let fd=new FormData(form);for(let k of Object.keys(checkout))checkout[k]=String(fd.get(k)||'');checkout.state=checkout.state.toUpperCase();write('suits-checkout',checkout);checkoutStage=1;render()}
async function fetchCheckoutQuote(){const key=JSON.stringify({bag,checkout});if(checkoutQuoteBusy||(checkoutQuote&&checkoutQuote.key===key))return;checkoutQuoteBusy=true;try{const response=await fetch('/api/checkout/quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:bag,shipping:checkout})});const data=await response.json();if(!response.ok)throw Error(data.error||'Unable to calculate your total.');checkoutQuote={key,...data};checkoutQuoteBusy=false;if((location.hash||'')==='#checkout')render(false)}catch(e){checkoutQuote={key,failed:true};checkoutQuoteBusy=false}}
function checkoutKey(){const fingerprint=JSON.stringify({bag,checkout});let previous=read('suits-checkout-attempt',null);if(!previous||previous.fingerprint!==fingerprint){previous={fingerprint,key:uid()};write('suits-checkout-attempt',previous)}return previous.key}
async function submitCheckout(){if(!$('#orderConsent').checked){$('#checkoutError').textContent='Please confirm that you’ve reviewed your order.';return}const b=$('#placeOrder');b.disabled=true;b.textContent='Preparing your order…';if(paymentConfig.ready){try{const response=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':checkoutKey()},body:JSON.stringify({items:bag,shipping:checkout})});const data=await response.json();if(!response.ok)throw Error(data.error||'Unable to begin payment.');write('suits-pending-order',data.orderId);const form=document.createElement('form');form.method='POST';form.action=data.paymentUrl;const input=document.createElement('input');input.type='hidden';input.name='token';input.value=data.token;form.append(input);document.body.append(form);form.submit();return}catch(e){$('#checkoutError').textContent=e.message;b.disabled=false;b.textContent='Try again →';return}}
const order={id:'DEMO-'+Date.now().toString(36).toUpperCase(),created:new Date().toISOString(),items:JSON.parse(JSON.stringify(bag)),shipping:{...checkout},total:subtotal(),status:'Demo order recorded',demo:true};orders.unshift(order);write('suits-orders',orders);bag=[];write('suits-bag',bag);updateBag();location.hash='#order/'+order.id;render()}
function orderPage(id){const o=orders.find(o=>o.id===id)||(accountState.user?mergedOrders().find(o=>o.id===id):null);if(!o){if(accountState.user)ensureAccountOrders();return ordersPage()}return `<section class="order-complete"><span class="complete-check">✓</span><span class="eyebrow">${o.demo?'DEMONSTRATION COMPLETE':'YOUR ORDER'}</span><h1>${o.demo?'A look that’s entirely yours.':'Thank you for your order.'}</h1><p>${o.demo?'Your sample order is saved. No payment was taken, and no production order was submitted.':'Your order has been received.'}</p><div class="order-id">${esc(o.id)} · ${new Date(o.created).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</div><div class="order-complete-details"><div><h3>Delivery details</h3><p>${esc(o.shipping.firstName)} ${esc(o.shipping.lastName)}<br>${esc(o.shipping.address)}<br>${esc(o.shipping.city)}, ${esc(o.shipping.state)} ${esc(o.shipping.zip)}</p></div><div><h3>Order status</h3><p>${esc(o.status)}<br>${orderNeedsMeasurements(o)?'Measurements: to follow. This order stays incomplete until they are added.<br>':''}${o.demo?'No email sent for demo orders.':'Payment status is verified separately.'}</p></div></div>${o.items.map((x,idx)=>lineHtml(x,false)+deferredAttachHtml(o,x,idx)).join('')}<div class="total"><span>Total</span><strong>${money(o.total)}</strong></div><a class="btn orange" href="/collections/suits">Continue exploring →</a><a class="btn light" href="/orders">My orders</a></section>`}
function ordersPage(){if(accountState.enabled&&accountState.user){ensureAccountOrders();const list=mergedOrders();return `<section class="content-page"><span class="eyebrow">YOUR PERSONAL WARDROBE</span><h1>Your orders.</h1><p>Orders from your account and this browser. Imported demo orders stay marked as demo records.</p>${list.length?list.map(o=>orderRowHtml(o)).join(''):`<div class="empty"><h2>Your story starts with one piece.</h2><p>Once you complete a checkout, your order will appear here.</p><a class="btn orange" href="/collections/suits">Explore the collection →</a></div>`}</section>`}return `<section class="content-page"><span class="eyebrow">YOUR PERSONAL WARDROBE</span><h1>Your orders.</h1><p>Orders saved on this browser.</p>${orders.length?orders.map(o=>`<a class="order-row" href="/orders/${o.id}"><div><strong>${esc(o.id)}</strong><p>${o.items.length} ${o.items.length===1?'item':'items'} · ${new Date(o.created).toLocaleDateString()}${orderNeedsMeasurements(o)?' · Measurements to follow':''}</p></div><span>${money(o.total)}</span><span>${esc(o.status)} →</span></a>`).join(''):`<div class="empty"><h2>Your story starts with one piece.</h2><p>Once you complete a checkout, your order will appear here.</p><a class="btn orange" href="/collections/suits">Explore the collection →</a></div>`}</section>`}
function giftPage(){return `<section class="gift-page"><div class="gift-art"><img src="assets/model-accessories.webp" alt="Thoughtful tailoring accessories"><div class="gift-card"><img src="assets/mysuit-logo.png" alt="suits.me"><span>THE GIFT OF PERSONAL STYLE</span><strong id="giftPreview">$100</strong></div></div><div class="gift-copy"><span class="eyebrow">A THOUGHTFUL GESTURE</span><h1>Something<br>entirely theirs.</h1><p>Let them choose the fabric, the details, and the moment.</p><form onsubmit="event.preventDefault();addGift(this)"><label class="field">Gift amount<select name="amount" onchange="document.getElementById('giftPreview').textContent='$'+this.value">${[100,200,300,500,750,1000].map(n=>`<option value="${n}">$${n}</option>`).join('')}</select></label><label class="field">Recipient’s name<input name="recipient" required maxlength="60" placeholder="Who’s the lucky one?"></label><label class="field">Recipient’s email<input name="email" type="email" required maxlength="150" placeholder="name@example.com"></label><label class="field">A personal message<textarea name="message" maxlength="300" rows="3" placeholder="Make it personal…"></textarea></label><button class="btn orange" type="submit">Add gift card to bag →</button><p class="subtle" style="margin-top:15px">Demo gift cards do not create redeemable credit or send email.</p></form></div></section>`}
function addGift(form){let f=new FormData(form),p=products.findIndex(p=>p.kind==='gift');if(p<0){products.push({name:'The Suits.me Gift Card',fabric:'Digital gift card',color:'Digital',price:100,img:'model-accessories.webp',category:'Gifts',kind:'gift'});p=products.length-1}addDirect(p,{gift:{amount:Number(f.get('amount')),recipient:String(f.get('recipient')),email:String(f.get('email')),message:String(f.get('message'))}})}
