function policyPage(kind){const content={shipping:['Delivery & garment care.','A considered purchase deserves a personal conversation.','Custom tailoring involves garment-specific fabric availability, production, and fitting. Your stylist can confirm the current delivery estimate, alteration arrangements, and returns policy before a live order is placed.','For current business terms, consult Suits.me’s published shipping and returns policy.','https://www.suits.me/shipping-returns'],privacy:['Your details, thoughtfully handled.','A clear view of what this experience saves.','This preview saves measurement profiles, bag contents, checkout details, and demo orders in your browser storage. Card details are never requested in demo mode. A configured live checkout sends payment details directly to Authorize.Net through its hosted form.','To remove information stored by this preview on this browser, use the control below. The business’s published privacy policy covers its existing services.','https://www.suits.me/privacy-policy'],terms:['The details of this experience.','An interactive design and shopping preview.','The catalog, garment imagery, prices, and demo orders illustrate the proposed storefront. Demo orders do not create a purchase contract, reserve inventory, send a gift card, or enter production. Live selling requires approved catalog data, merchant configuration, and business policies.','For the current business terms, see Suits.me’s published terms of service.','https://www.suits.me/terms-of-service']}[kind];return `<section class="content-page policy-page"><span class="eyebrow">CUSTOMER CARE</span><h1>${content[0]}</h1><h2>${content[1]}</h2><p>${content[2]}</p><p>${content[3]}</p><a class="btn light" href="${content[4]}" target="_blank" rel="noopener">Read the business policy ↗</a>${kind==='privacy'?'<button class="btn light" style="margin:15px 0" onclick="confirmClearData()">Clear this preview’s browser data</button>':''}<p style="margin-top:35px">Need a little guidance? <a class="textlink" href="/locations">Contact a showroom →</a></p></section>`}
function confirmClearData(){openModal('<h2>Clear your saved details?</h2><p>This removes the profiles, bag, checkout details, and demo orders saved by this preview on this browser.</p><button class="btn orange" onclick="clearPreviewData()">Clear saved details</button><button class="btn light" style="margin:10px" onclick="closeModal()">Keep my details</button>')}
function clearPreviewData(){for(const k of ['suits-profiles','suits-bag','suits-checkout','suits-orders','suits-draft','suits-config','suits-clone-plan','suits-pending-order','suits-checkout-attempt'])localStorage.removeItem(k);closeModal();location.reload()}
async function paymentReturnPage(){const id=read('suits-pending-order',null);$('#main').innerHTML=`<section class="center-page"><span class="eyebrow">AUTHORIZE.NET CHECKOUT</span><h1>Checking your payment.</h1><p>We’re confirming your transaction securely.</p></section>`;if(!id){$('#main').innerHTML='<section class="center-page"><h1>Let’s find your order.</h1><p>No pending payment was found on this browser.</p><a class="btn orange" href="/orders">View orders →</a></section>';return}try{const r=await fetch('/api/orders/'+encodeURIComponent(id)),o=await r.json();if(!r.ok)throw Error(o.error||'Unable to check payment');if(o.status==='paid'){if(!orders.some(x=>x.id===o.id)){orders.unshift({...o,demo:false,created:o.created_at,total:o.total_cents/100});write('suits-orders',orders)}bag=[];write('suits-bag',bag);location.hash='#order/'+o.id}else if(o.status==='expired'){$('#main').innerHTML=`<section class="center-page"><span class="eyebrow">PAYMENT VERIFICATION</span><h1>This order has expired.</h1><p>Order reference: ${esc(id)}. An unpaid order can be paid within 24 hours of starting checkout, and this order's window has closed, so no payment can be taken against it. If you did complete a payment, contact us with your order reference and we will check it for you. Your bag is unchanged: return to checkout, and starting again creates a fresh order in its place.</p><a class="btn orange" href="/checkout">Return to checkout</a><a class="btn light" href="/locations">Contact a showroom</a></section>`}else $('#main').innerHTML=`<section class="center-page"><span class="eyebrow">PAYMENT VERIFICATION</span><h1>Your payment is being confirmed.</h1><p>Order reference: ${esc(id)}. Keep this reference if you contact us. Please don’t submit another payment while confirmation is pending.</p><button class="btn orange" onclick="paymentReturnPage()">Check status →</button><a class="btn light" href="/locations">Contact a showroom</a></section>`}catch(e){$('#main').innerHTML=`<section class="center-page"><h1>Let’s check that again.</h1><p>${esc(e.message)}</p><button class="btn orange" onclick="paymentReturnPage()">Retry payment status →</button><a class="btn light" href="/locations">Get help</a></section>`}}
// Wave 5 package 5.4 (ACC-01): account screens and entry points.
// The client learns identity only from GET /api/auth/me, fetched at
// boot below: the session cookie is HttpOnly and never readable
// here. accountState starts disabled, so until that fetch answers
// with enabled: true there is no sign in entry point anywhere and
// the guest experience is exactly the one the storefront already
// had: the header slot stays empty, checkout carries no account
// strip and the profiles modal keeps its browser only line. The
// forms below speak to the package 5.2 endpoints and display the
// responses those endpoints return; the uniform register, resend
// and forgot password answers are shown word for word, so the
// screens cannot reveal whether an account exists for an address.
function queryParam(name){const parts=[String(location.search||'').replace(/^\?/,''),String(location.hash||'').split('?')[1]||''];for(const part of parts){for(const pair of part.split('&')){if(!pair)continue;const i=pair.indexOf('=');if((i<0?pair:pair.slice(0,i))===name){const raw=i<0?'':pair.slice(i+1);try{return decodeURIComponent(raw)}catch{return raw}}}}return null}
// The returnTo rules of app/chatgpt-auth.ts, applied to the app
// account screens: a relative path starting with /, never //, and
// never an auth path; anything else falls back to /account.
function validReturnTo(value){if(typeof value!=='string'||!value.startsWith('/')||value.startsWith('//')||value.includes('://'))return '/account';const path=value.split(/[?#]/)[0];if(['/sign-in','/register','/forgot-password','/reset-password','/verify-email','/signin-with-chatgpt','/signout-with-chatgpt','/callback'].includes(path))return '/account';return value}
function goToReturn(value){const target=validReturnTo(value);const hash=typeof hashForRealPath==='function'?hashForRealPath(target.split('?')[0]):null;if(hash){location.hash=hash;render()}else if(target==='/account'){location.hash='#account';render()}else if(target==='/'){location.hash='#home';render()}else{location.href=target}}
async function authPost(path,body){try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let data=null;try{data=await r.json()}catch{}return{ok:r.ok,status:r.status,data}}catch{return{ok:false,status:0,data:null}}}
// Wave 5 package 5.5 (ACC-01, SIZ-04): profile sync and the guest
// migration, design sections 2.6 and 5. While signed in, the server
// list is the account's copy of the shopper's profiles and the local
// array is kept mirrored to it: saves and deletes go to the API (the
// hooks app.js calls as it updates local storage), and signing in
// pulls the account list down into this browser. A failed write
// never drops a measurement: the local change is kept, the profile
// id waits in profileSyncPending, and the profiles modal shows the
// design's "Not saved to your account yet" line until a later sync
// succeeds.
const profileSyncPending=new Set();
async function accountFetch(path,opts={}){try{const r=await fetch(path,opts);let data=null;try{data=await r.json()}catch{}return{ok:r.ok,status:r.status,data}}catch{return{ok:false,status:0,data:null}}}
function accountProfileCopy(profile){const copy={...profile};delete copy.step;return copy}
async function pushProfileToAccount(profile){if(!accountState.user)return;const{ok}=await accountFetch('/api/account/profiles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile:accountProfileCopy(profile)})});if(ok)profileSyncPending.delete(profile.id);else profileSyncPending.add(profile.id)}
function syncProfileToAccount(profile){pushProfileToAccount(profile)}
async function deleteProfileOnAccount(id){if(!accountState.user)return;const{ok}=await accountFetch('/api/account/profiles/'+encodeURIComponent(id),{method:'DELETE'});if(ok)profileSyncPending.delete(id);else profileSyncPending.add(id)}
function syncProfileDeleteToAccount(id){deleteProfileOnAccount(id)}
// Retry whatever a failed connection left outstanding: a pending id
// that still exists locally is the save that never landed, and one
// that no longer exists is the delete that never landed.
async function flushProfileSync(){if(!accountState.user||!profileSyncPending.size)return;for(const id of[...profileSyncPending]){const local=profiles.find(p=>p.id===id);if(local)await pushProfileToAccount(local);else await deleteProfileOnAccount(id)}}
// Pull the account's profiles into this browser. Ids the server does
// not hold stay local (they are what the migration offer below is
// about); ids it does hold take the server copy, except one with a
// local change still waiting to sync, which is never overwritten.
async function pullAccountProfiles(){if(!accountState.user)return;const{ok,data}=await accountFetch('/api/account/profiles');if(!ok||!data||!Array.isArray(data.profiles))return;let changed=false;for(const serverProfile of data.profiles){if(!serverProfile||typeof serverProfile.id!=='string')continue;const index=profiles.findIndex(p=>p.id===serverProfile.id);if(index<0){profiles.push(serverProfile);changed=true}else if(!profileSyncPending.has(serverProfile.id)&&JSON.stringify(accountProfileCopy(profiles[index]))!==JSON.stringify(serverProfile)){profiles[index]=serverProfile;changed=true}}if(changed)write('suits-profiles',profiles)}
async function syncAccountProfiles(){await pullAccountProfiles();await flushProfileSync()}
// The guest migration (design section 5): offered once, after the
// first successful sign in or verification on a browser that holds
// local data. "Not now" is remembered per account on this browser
// under the design's flag, and a completed import is remembered the
// same way, so the shopper is asked once, not every sign in. Nothing
// is ever deleted locally, and the bag is never part of the import:
// the client posts the full local profile and order arrays, and the
// server stores the orders as view only demo snapshots.
function importFlag(kind){return 'suits-import-'+kind+':'+(accountState.user?accountState.user.id:'')}
function migrationOfferHtml(){const count=profiles.length;return `<div class="eyebrow">YOUR PERSONAL FIT</div><h2>Your measurements, saved to your account.</h2><p>This browser has ${count} measurement profile${count===1?'':'s'} saved. Add them to your account so they are there on any device? Your orders recorded on this browser (${orders.length}) come along as view only history, marked as demo records. Nothing is removed from this browser.</p><div id="importError" class="error" role="alert"></div><button class="btn orange" onclick="confirmImport()">Add to my account</button><button class="btn light" style="margin-top:12px" onclick="dismissImport()">Not now</button>`}
function maybeOfferImport(){if(!accountState.user)return;try{if(localStorage.getItem(importFlag('dismissed'))||localStorage.getItem(importFlag('done')))return}catch{}if(!profiles.length&&!orders.length)return;openModal(migrationOfferHtml())}
async function postImport(){const{ok,data}=await accountFetch('/api/account/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profiles,orders})});if(ok&&data){accountOrders=null;accountOrdersFor=null;return data}return null}
function importSummary(result){const profileLine=`Added ${result.profilesImported} profile${result.profilesImported===1?'':'s'}; ${result.profilesSkipped} ${result.profilesSkipped===1?'was':'were'} already in your account.`;const orderLine=result.ordersImported||result.ordersSkipped?`Added ${result.ordersImported} order${result.ordersImported===1?'':'s'} as view only history; ${result.ordersSkipped} ${result.ordersSkipped===1?'was':'were'} already in your account.`:'';return{profileLine,orderLine}}
async function confirmImport(){const result=await postImport();if(!result){const box=$('#importError');if(box)box.textContent='We could not add them just now. Your profiles and orders are still saved on this browser, and you can try again from your account page.';return}try{localStorage.setItem(importFlag('done'),'1')}catch{}const{profileLine,orderLine}=importSummary(result);openModal(`<div class="eyebrow">YOUR PERSONAL FIT</div><h2>Added to your account.</h2><p>${profileLine}</p>${orderLine?`<p>${orderLine}</p>`:''}<p class="subtle">Nothing was removed from this browser.</p><button class="btn orange" onclick="closeModal()">Done</button>`)}
function dismissImport(){try{localStorage.setItem(importFlag('dismissed'),'1')}catch{}closeModal()}
// The same import, run from the account page whenever the shopper
// asks for it (design section 5.1), whatever the modal decided.
async function importFromAccount(){const result=await postImport();const error=$('#importError'),message=$('#importMessage');if(!result){if(error)error.textContent='We could not import from this browser just now. Nothing was changed; your profiles and orders are still saved on this browser.';return}try{localStorage.setItem(importFlag('done'),'1')}catch{}const{profileLine,orderLine}=importSummary(result);if(error)error.textContent='';if(message)message.textContent=profileLine+(orderLine?' '+orderLine:'')}
// Wave 5 package 5.6 (ACC-01): the merged account orders view.
// The server half is GET /api/account/orders (lib/accounts.ts),
// which returns the signed in user's real orders in the store
// order shape combined with their imported demo snapshots, each
// snapshot marked demo and imported; checkout keys new orders to
// the same account through the shared owner resolver in
// lib/commerce.ts. Here the orders page renders one history while
// signed in: this browser's orders merged with the account list,
// the account copy winning a shared id (the server list is the
// account's copy, the same rule profiles follow), newest first,
// snapshots badged as demo records. The cache is keyed to the
// user it was loaded for, so a different account signing in on
// this browser never sees the previous account's list, and
// signing out returns the page to the local list alone: the
// signed out and disabled rendering is the pre Wave 5 page, byte
// for byte, because the merge only runs while accountState
// holds a user.
let accountOrders=null,accountOrdersFor=null,accountOrdersLoading=false;
function accountOrderShape(o){if(!o||o.imported)return o;return{id:o.id,created:o.created_at,items:o.items,shipping:o.shipping,status:o.status,total:(o.total_cents||0)/100,demo:false}}
function mergedOrders(){const byId=new Map();for(const o of orders)byId.set(o.id,o);if(accountState.user&&accountOrders&&accountOrdersFor===accountState.user.id)for(const raw of accountOrders){const o=accountOrderShape(raw);if(o&&o.id)byId.set(o.id,o)}return[...byId.values()].sort((a,b)=>String(b.created||'').localeCompare(String(a.created||'')))}
async function loadAccountOrders(){if(!accountState.user||accountOrdersLoading)return;const userId=accountState.user.id;accountOrdersLoading=true;const{ok,data}=await accountFetch('/api/account/orders');accountOrdersLoading=false;if(!ok||!data||!Array.isArray(data.orders))return;accountOrders=data.orders;accountOrdersFor=userId;const h=location.hash||'';if(h==='#orders'||h.startsWith('#order/'))render(false)}
function ensureAccountOrders(){if(!accountState.user)return;if(accountOrders&&accountOrdersFor===accountState.user.id)return;loadAccountOrders()}
function orderRowHtml(o){return `<a class="order-row" href="/orders/${o.id}"><div><strong>${esc(o.id)}</strong><p>${o.items.length} ${o.items.length===1?'item':'items'} · ${new Date(o.created).toLocaleDateString()}</p></div>${o.demo?'<span class="demo-badge">Demo record</span>':''}${orderNeedsMeasurements(o)?'<span class="demo-badge">Measurements to follow</span>':''}<span>${money(o.total)}</span><span>${esc(o.status)} →</span></a>`}
// Measurements wave package M6 (owner decision O7): deferred
// measurements. An item ordered with measurements to follow
// carries a profile with method 'deferred' and no values at all:
// it is an order state, never a saved profile, and it never
// enters the profiles list. The orders list and the order page
// mark such an order incomplete, and the shopper completes it
// from the order page: attach a saved profile that fits the
// garment, or take the measurements in the garment studio, whose
// save then attaches the new profile through
// maybeAttachSavedProfile (the hook the studio save paths in
// app.js call). Demo orders complete in this browser's records;
// server orders complete through POST
// /api/orders/:id/measurements, which cleans the profile with
// the same server rule checkout uses, and the local mirror and
// the account orders cache are updated from its answer. Imported
// demo snapshots stay view only history (package 5.5) and are
// not completed here; the browser's own copy of such an order
// is the one that completes.
let pendingOrderAttach=null;
function orderItemDeferred(x){return !!x&&x.profile?.method==='deferred'}
function orderNeedsMeasurements(o){return !!o&&Array.isArray(o.items)&&o.items.some(orderItemDeferred)}
function resolveOrder(id){return orders.find(o=>o.id===id)||(accountState.user?mergedOrders().find(o=>o.id===id):null)||null}
function deferredAttachHtml(o,x,idx){if(!orderItemDeferred(x))return'';return `<div class="deferred-actions"><p><strong>Measurements to follow.</strong> We cannot start making this garment until you add them.</p><button class="btn orange" type="button" onclick="openOrderMeasurements('${o.id}',${idx})">Add measurements</button></div>`}
function attachCandidates(item){const p=products[item.product];if(!p)return[];const wearer=item.profile?.wearer||productWearerOf(p);return profiles.filter(q=>(q.wearer||'Men')===wearer&&(profileVersion(q)!==2||!q.garment||q.garment===p.kind))}
function openOrderMeasurements(orderId,index){const o=resolveOrder(orderId),item=o?.items?.[index];if(!item||!orderItemDeferred(item))return;const p=products[item.product],candidates=attachCandidates(item);openModal(`<div class="eyebrow">MEASUREMENTS TO FOLLOW</div><h2>Add measurements for ${esc(p?p.name:'your garment')}.</h2><p>This item was ordered with measurements to follow, so its order is incomplete. Attach a saved profile for this garment, or take your measurements now. The garment will be made from the profile you attach; nothing is filled in for you.</p><div id="attachError" class="error" role="alert"></div>${candidates.length?candidates.map(q=>`<div class="profile-item"><h3>${esc(q.name)}</h3><p class="subtle">${q.method==='ready'?'Standard size':q.method==='garment'?'Garment measurements':q.method==='modify'?'Modified standard size':'Body measurements'} · ${esc(q.wearer||'Men')}</p><button class="btn light" type="button" onclick="attachProfileToOrder('${orderId}',${index},'${q.id}')">Use this profile</button></div>`).join(''):'<p class="subtle">You have no saved profile for this garment yet.</p>'}<button class="btn orange" type="button" onclick="measureForOrderItem('${orderId}',${index})">Take my measurements →</button><button class="btn light" style="margin-top:12px" type="button" onclick="closeModal()">Not now</button>`)}
async function attachProfileToOrder(orderId,index,profileId){const profile=profiles.find(q=>q.id===profileId);if(!profile)return;const local=orders.find(o=>o.id===orderId);
if(local&&local.demo){local.items[index].profile=JSON.parse(JSON.stringify(profile));write('suits-orders',orders);closeModal();location.hash='#order/'+orderId;render();toast('Measurements added to your order.');return}
try{const r=await fetch('/api/orders/'+encodeURIComponent(orderId)+'/measurements',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({index,profile:accountProfileCopy(profile)})});const data=await r.json();if(!r.ok)throw Error(data.error||'We could not add those measurements just now.');
if(local){local.items=data.items;write('suits-orders',orders)}
if(accountOrders){const at=accountOrders.findIndex(o=>o.id===orderId);if(at>=0)accountOrders[at]=data}
closeModal();location.hash='#order/'+orderId;render();toast('Measurements added to your order.');}catch(e){const box=$('#attachError');if(box)box.textContent=e.message;toast(e.message)}}
function measureForOrderItem(orderId,index){const o=resolveOrder(orderId),item=o?.items?.[index];if(!item||!orderItemDeferred(item))return;closeModal();beginDesign(item.product);pendingOrderAttach={orderId,index};startMeasurements()}
function maybeAttachSavedProfile(p){if(!pendingOrderAttach)return false;const ctx=pendingOrderAttach;pendingOrderAttach=null;returnToSuit=false;attachProfileToOrder(ctx.orderId,ctx.index,p.id);return true}
// What runs each time a flow establishes the signed in user: the
// account's profiles sync with this browser, then the one time
// migration offer is made if this browser holds local data.
async function afterSignIn(){await syncAccountProfiles();maybeOfferImport()}
function renderAccountNav(){const el=$('#accountNav');if(!el)return;if(!accountState.enabled){el.innerHTML='';return}if(!accountState.user){el.innerHTML=`<a class="measurement-shortcut" href="${realUrl('#sign-in')}">Sign in</a>`;return}const label=String(accountState.user.name||accountState.user.email||'').trim();const initial=esc((label.charAt(0)||'A').toUpperCase());el.innerHTML=`<details class="account-menu"><summary class="account-button" aria-label="Your account" title="${esc(accountState.user.email)}">${initial}</summary><div class="account-menu-list"><a href="${realUrl('#account')}">My account</a><a href="${realUrl('#orders')}">My orders</a><button type="button" onclick="signOut()">Sign out</button></div></details>`}
function accountStrip(){if(!accountState.enabled)return '';if(accountState.user)return `<p class="account-strip">Signed in as ${esc(accountState.user.email)}. Your profiles sync to your account.</p>`;const href=realUrl('#sign-in');return `<p class="account-strip">Have an account? <a href="${href.startsWith('/')?href+'?returnTo=/checkout':href}">Sign in</a> to use your saved measurements.</p>`}
function authLoading(title){return `<section class="content-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>${title}</h1><p class="subtle">One moment, please.</p></section>`}
function authUnavailable(){return `<section class="content-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Accounts are not available yet.</h1><p>We are still setting up account sign in. Your measurement profiles and orders stay saved on this browser in the meantime.</p><a class="btn orange" href="${realUrl('#orders')}">View your orders →</a></section>`}
function signInPage(){if(!accountState.loaded)return authLoading('Welcome back.');if(!accountState.enabled)return authUnavailable();if(accountState.user)return accountPage();return `<section class="content-page auth-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Welcome back.</h1><p>Sign in to use your saved measurement profiles on any device.</p><form onsubmit="event.preventDefault();submitSignIn(this)"><label class="field">Email<input name="email" type="email" required autocomplete="email"></label><label class="field">Password<input name="password" type="password" required autocomplete="current-password"></label><div id="signInError" class="error" role="alert"></div><button class="btn orange" type="submit">Sign in →</button></form><p><a href="${realUrl('#forgot-password')}">Forgot your password?</a></p><p>New to Suits.me? <a href="${realUrl('#register')}">Create an account</a></p></section>`}
async function submitSignIn(form){const fd=new FormData(form);const{ok,data}=await authPost('/api/auth/sign-in',{email:String(fd.get('email')||''),password:String(fd.get('password')||'')});if(ok&&data&&data.user){accountState={enabled:true,loaded:true,user:data.user};renderAccountNav();afterSignIn();goToReturn(queryParam('returnTo'));return}$('#signInError').textContent=data&&data.error?data.error:'We could not sign you in. Please try again.'}
function registerPage(){if(!accountState.loaded)return authLoading('Create your account.');if(!accountState.enabled)return authUnavailable();if(accountState.user)return accountPage();return `<section class="content-page auth-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Create your account.</h1><p>We will email you a link to confirm your address. Your measurements stay on this device until you sign in.</p><form onsubmit="event.preventDefault();submitRegister(this)"><label class="field">Name<input name="name" type="text" required maxlength="120" autocomplete="name"></label><label class="field">Email<input name="email" type="email" required autocomplete="email"></label><label class="field">Password<input name="password" type="password" required autocomplete="new-password"></label><div id="registerError" class="error" role="alert"></div><p id="registerMessage" role="status"></p><button class="btn orange" type="submit">Create account →</button></form><p>Already have an account? <a href="${realUrl('#sign-in')}">Sign in</a></p></section>`}
async function submitRegister(form){const fd=new FormData(form);const{ok,data}=await authPost('/api/auth/register',{name:String(fd.get('name')||''),email:String(fd.get('email')||''),password:String(fd.get('password')||'')});if(ok&&data){$('#registerError').textContent='';$('#registerMessage').textContent=data.message||'';return}$('#registerError').textContent=data&&data.error?data.error:'We could not create your account. Please try again.'}
function forgotPasswordPage(){if(!accountState.loaded)return authLoading('Forgot your password.');if(!accountState.enabled)return authUnavailable();return `<section class="content-page auth-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Forgot your password.</h1><p>Tell us the email for your account and we will send a reset link if an account matches.</p><form onsubmit="event.preventDefault();submitForgotPassword(this)"><label class="field">Email<input name="email" type="email" required autocomplete="email"></label><div id="forgotError" class="error" role="alert"></div><p id="forgotMessage" role="status"></p><button class="btn orange" type="submit">Send a reset link →</button></form><p class="subtle">If you created an account but never confirmed your email, create your account again with the same address and we will send a fresh confirmation link.</p><p><a href="${realUrl('#sign-in')}">Back to sign in</a></p></section>`}
async function submitForgotPassword(form){const fd=new FormData(form);const{ok,data}=await authPost('/api/auth/forgot-password',{email:String(fd.get('email')||'')});if(ok&&data){$('#forgotError').textContent='';$('#forgotMessage').textContent=data.message||'';return}$('#forgotError').textContent=data&&data.error?data.error:'We could not send a reset link. Please try again.'}
function resetPasswordPage(){if(!accountState.loaded)return authLoading('Choose a new password.');if(!accountState.enabled)return authUnavailable();const token=queryParam('token')||'';return `<section class="content-page auth-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Choose a new password.</h1><p>Use at least 12 characters. A longer phrase you can remember works best.</p><form onsubmit="event.preventDefault();submitResetPassword(this)"><input type="hidden" name="token" value="${esc(token)}"><label class="field">New password<input name="password" type="password" required autocomplete="new-password"></label><label class="field">Confirm new password<input name="confirmation" type="password" required autocomplete="new-password"></label><div id="resetError" class="error" role="alert"></div><button class="btn orange" type="submit">Set my new password →</button></form><p><a href="${realUrl('#forgot-password')}">Request a new link</a></p></section>`}
async function submitResetPassword(form){const fd=new FormData(form);const password=String(fd.get('password')||'');if(password!==String(fd.get('confirmation')||'')){$('#resetError').textContent='The passwords do not match.';return}const{ok,data}=await authPost('/api/auth/reset-password',{token:String(fd.get('token')||''),password});if(ok&&data&&data.user){accountState={enabled:true,loaded:true,user:data.user};renderAccountNav();location.hash='#account';render();afterSignIn();return}$('#resetError').textContent=data&&data.error?data.error:'We could not reset your password. Please try again.'}
let verifyAttempt={token:null,status:'idle'};
function verifyHtml(state){if(state==='posting')return `<section class="content-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Confirming your email.</h1><p>One moment while we confirm this link.</p></section>`;if(state==='done')return `<section class="content-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Your email is confirmed.</h1><p>You are signed in.</p><a class="btn orange" href="${realUrl('#account')}">Go to your account →</a></section>`;if(state==='disabled')return authUnavailable();return `<section class="content-page auth-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Confirm your email.</h1><p class="error" role="alert">This link is invalid or has expired.</p><p>Ask for a fresh confirmation link and we will email it to you.</p><form onsubmit="event.preventDefault();resendVerification(this)"><label class="field">Email<input name="email" type="email" required autocomplete="email"></label><div id="verifyError" class="error" role="alert"></div><p id="verifyMessage" role="status"></p><button class="btn orange" type="submit">Send a new link →</button></form><p><a href="${realUrl('#sign-in')}">Back to sign in</a></p></section>`}
async function verifyEmailPage(){const token=queryParam('token')||'';if(verifyAttempt.token===token&&verifyAttempt.status!=='idle'){$('#main').innerHTML=verifyHtml(verifyAttempt.status);$('#main').setAttribute('data-route','#verify-email');return}verifyAttempt={token,status:'posting'};$('#main').innerHTML=verifyHtml('posting');$('#main').setAttribute('data-route','#verify-email');if(!token){verifyAttempt={token,status:'invalid'};$('#main').innerHTML=verifyHtml('invalid');return}const{status,data}=await authPost('/api/auth/verify-email',{token});if(status===503){verifyAttempt={token,status:'disabled'};if((location.hash||'')==='#verify-email')$('#main').innerHTML=verifyHtml('disabled');return}if(data&&data.user){accountState={enabled:true,loaded:true,user:data.user};renderAccountNav();verifyAttempt={token,status:'done'};location.hash='#account';render();afterSignIn();return}verifyAttempt={token,status:'invalid'};if((location.hash||'')==='#verify-email')$('#main').innerHTML=verifyHtml('invalid')}
async function resendVerification(form){const fd=new FormData(form);const{ok,data}=await authPost('/api/auth/resend-verification',{email:String(fd.get('email')||'')});if(ok&&data){$('#verifyError').textContent='';$('#verifyMessage').textContent=data.message||'';return}$('#verifyError').textContent=data&&data.error?data.error:'We could not send a new link. Please try again.'}
function accountPage(){if(!accountState.loaded)return authLoading('Your account.');if(!accountState.enabled)return authUnavailable();const user=accountState.user;if(!user)return `<section class="content-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Your account.</h1><p>You are not signed in on this browser. Sign in to use your saved measurement profiles on any device; your profiles and orders on this browser stay right where they are either way.</p><a class="btn orange" href="${realUrl('#sign-in')}">Sign in →</a> <a class="btn light" href="${realUrl('#register')}">Create an account</a></section>`;return `<section class="content-page"><span class="eyebrow">YOUR ACCOUNT</span><h1>Your account.</h1><p><strong>${esc(user.name||user.email)}</strong><br>${esc(user.email)}</p><p class="subtle">Email ${user.emailVerified?'confirmed':'not confirmed yet'}.</p><p><a class="btn light" href="${realUrl('#orders')}">My orders</a> <button class="btn light" type="button" onclick="openProfiles()">Measurement profiles</button></p><h2>Import from this browser.</h2><p class="subtle">Add the measurement profiles and recorded orders saved on this browser to your account. Orders come along as view only history, marked as demo records, and nothing is removed from this browser.</p><div id="importError" class="error" role="alert"></div><p id="importMessage" role="status"></p><p><button class="btn light" type="button" onclick="importFromAccount()">Import from this browser</button></p><h2>Change your password.</h2><form onsubmit="event.preventDefault();submitChangePassword(this)"><label class="field">Current password<input name="currentPassword" type="password" required autocomplete="current-password"></label><label class="field">New password<input name="newPassword" type="password" required autocomplete="new-password"></label><div id="changePasswordError" class="error" role="alert"></div><p id="changePasswordMessage" role="status"></p><button class="btn orange" type="submit">Change password →</button></form><p><button class="btn light" type="button" onclick="signOut()">Sign out</button></p></section>`}
async function submitChangePassword(form){const fd=new FormData(form);const{ok,data}=await authPost('/api/auth/change-password',{currentPassword:String(fd.get('currentPassword')||''),newPassword:String(fd.get('newPassword')||'')});if(ok&&data){if(data.user)accountState.user=data.user;$('#changePasswordError').textContent='';$('#changePasswordMessage').textContent='Your password has been changed.';renderAccountNav();return}$('#changePasswordError').textContent=data&&data.error?data.error:'We could not change your password. Please try again.'}
async function signOut(){await authPost('/api/auth/sign-out',{});accountState={enabled:accountState.enabled,loaded:true,user:null};renderAccountNav();render()}
render=function(top=true){const h=location.hash||'#home';if(h==='#payment-return'){paymentReturnPage();return}if(h==='#verify-email'){verifyEmailPage();return}let html=h.startsWith('#collection')?categoryCollection(h):h.startsWith('#product/')?productPage(Number(h.split('/')[1])):h==='#customize'?customize():h==='#measure'?measure():h==='#checkout'?checkoutPage():h.startsWith('#order/')?orderPage(h.slice(7)):h==='#orders'?ordersPage():h==='#gift-cards'?giftPage():h==='#help'?helpPage():h==='#locations'?locationsPage():h==='#shipping'?policyPage('shipping'):h==='#privacy'?policyPage('privacy'):h==='#terms'?policyPage('terms'):h==='#sign-in'?signInPage():h==='#register'?registerPage():h==='#forgot-password'?forgotPasswordPage():h==='#reset-password'?resetPasswordPage():h==='#account'?accountPage():home();$('#main').innerHTML=html;$('#main').setAttribute('data-route',h);updateBag();document.title=(h.startsWith('#collection')?'The Collection':h==='#checkout'?'Checkout':h==='#measure'?'Your Measurements':h==='#sign-in'?'Sign In':h==='#register'?'Create Your Account':h==='#forgot-password'?'Forgot Password':h==='#reset-password'?'Reset Password':h==='#verify-email'?'Confirm Your Email':h==='#account'?'Your Account':'Made for You')+' - Suits.me';if(h==='#story'){document.getElementById('craft')?.scrollIntoView();return}if(top)window.scrollTo({top:0,left:0,behavior:'instant'})};
fetch('/api/payment/config').then(r=>r.ok?r.json():null).then(d=>{if(d){paymentConfig=d;if(location.hash==='#checkout')render(false)}}).catch(()=>{});
// The boot identity read. One race is handled on purpose: on the
// verify email landing this request is in flight while the screen
// posts its token, and the verification mints the first session, so
// a user a flow has already established is never overwritten by
// this older answer.
fetch('/api/auth/me').then(r=>r.ok?r.json():null).then(d=>{const flowUser=accountState.user;accountState={enabled:!!(d&&d.enabled)||!!flowUser,loaded:true,user:flowUser||(d&&d.user?d.user:null)};renderAccountNav();if(accountState.user)syncAccountProfiles();if(accountState.user&&(location.hash==='#orders'||(location.hash||'').startsWith('#order/')))ensureAccountOrders();if(['#checkout','#account','#sign-in','#register','#forgot-password','#reset-password'].includes(location.hash||''))render(false)}).catch(()=>{accountState.loaded=true;renderAccountNav();if(['#checkout','#account','#sign-in','#register','#forgot-password','#reset-password'].includes(location.hash||''))render(false)});
$('footer').innerHTML=`<div><a href="/"><img src="assets/mysuit-logo.png" alt="suits.me"></a><p>Personal tailoring. Individual style.</p><p class="subtle">New York · Made for everywhere.</p></div><div><span>EXPLORE</span><a href="/collections/suits">The collection</a><a href="/measure">Measurement studio</a><a href="/gift-cards">Gift cards</a><a href="/locations">Our showrooms</a></div><div><span>CUSTOMER CARE</span><a href="/help">Help & FAQs</a><a href="/orders">Your orders</a><a href="/shipping">Delivery & returns</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a></div><div class="footer-payment"><span>PAYMENT PARTNER</span><strong>Authorize.Net</strong><p>Secure hosted payments when merchant setup is enabled.</p><small>Design preview · AI-generated imagery<br>Illustrative catalog and pricing.</small></div><p class="copyright">© 2026 suits.me <span>GOOD CLOTH. PERSONAL DETAILS. YOUR PROPORTIONS.</span></p>`;
render();
